choices:
SELECT 사번, 월급
FROM 직원
ORDER BY 월급;

SELECT *
FROM 직원
WHERE 이름 LIKE '김%';

SELECT AVG(월급)
FROM 직원
WHERE 부서 = '인사팀';

SELECT SUM(부서, 월급)
FROM 직원
GROUP BY 부서;

SELECT e.이름, s.이름 AS 추천인이름
FROM 회원 e LEFT OUTER JOIN 회원 s
ON e.추천인아이디 = s.아이디;

SELECT e.이름, s.이름 AS 추천인이름
FROM 회원 e, 회원 s
WHERE e.추천인아이디 = s.아이디;
